using Microsoft.VisualStudio.TestTools.UnitTesting;
using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class StockLevelTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN-001"));
    }

    [TestMethod]
    public void AddStock_SingleAdd_IncreasesLevel()
    {
        _tracker.AddStock("SKU-A", 25);
        Assert.AreEqual(25, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_MultipleAdds_Accumulates()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-A", 15);
        Assert.AreEqual(25, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_ReducesLevel()
    {
        _tracker.AddStock("SKU-A", 30);
        _tracker.RemoveStock("SKU-A", 12);
        Assert.AreEqual(18, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_ExactAmount_LeavesZero()
    {
        _tracker.AddStock("SKU-A", 5);
        _tracker.RemoveStock("SKU-A", 5);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_ExceedsLevel_Throws()
    {
        _tracker.AddStock("SKU-A", 3);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-A", 10));
    }

    [TestMethod]
    public void RemoveStock_UnknownSku_Throws()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("GHOST", 1));
    }

    [TestMethod]
    public void IndependentSkus_DoNotInterfere()
    {
        _tracker.AddStock("A", 10);
        _tracker.AddStock("B", 20);
        Assert.AreEqual(10, _tracker.GetStockLevel("A"));
        Assert.AreEqual(20, _tracker.GetStockLevel("B"));
    }
}

[TestClass]
public class ValidationTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GetStockLevel_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.GetStockLevel(sku!));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-5)]
    public void AddStock_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-A", qty));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void RemoveStock_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-A", qty));
    }
}

[TestClass]
public class ReorderAlertTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    [TestMethod]
    public void NeedsReorder_BelowDefaultThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 5); // default threshold is 10
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_AtDefaultThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 10);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_AboveDefaultThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-A", 50);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("UNKNOWN"));
    }

    [TestMethod]
    public void NeedsReorder_CustomThreshold_UsesOverride()
    {
        _tracker.SetReorderThreshold("SKU-A", 3);
        _tracker.AddStock("SKU-A", 5);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_CustomThreshold_AtThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-A", 5);
        _tracker.AddStock("SKU-A", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void SetReorderThreshold_NegativeThreshold_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.SetReorderThreshold("SKU-A", -1));
    }

    [TestMethod]
    public void NeedsReorder_ChangedDefaultThreshold_Applies()
    {
        _tracker.ReorderThresholdDefault = 2;
        _tracker.AddStock("SKU-A", 3);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }
}

[TestClass]
public class WarehouseTransferTests
{
    private InventoryTracker _sourceWarehouse = null!;
    private InventoryTracker _destWarehouse = null!;

    [TestInitialize]
    public void Setup()
    {
        _sourceWarehouse = new InventoryTracker();
        _destWarehouse = new InventoryTracker();
    }

    [TestMethod]
    public void TransferTo_MovesStockBetweenWarehouses()
    {
        _sourceWarehouse.AddStock("SKU-A", 50);
        _sourceWarehouse.TransferTo(_destWarehouse, "SKU-A", 20);

        Assert.AreEqual(30, _sourceWarehouse.GetStockLevel("SKU-A"));
        Assert.AreEqual(20, _destWarehouse.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_EntireStock_LeavesSourceAtZero()
    {
        _sourceWarehouse.AddStock("SKU-A", 15);
        _sourceWarehouse.TransferTo(_destWarehouse, "SKU-A", 15);

        Assert.AreEqual(0, _sourceWarehouse.GetStockLevel("SKU-A"));
        Assert.AreEqual(15, _destWarehouse.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_ExceedsSourceStock_Throws()
    {
        _sourceWarehouse.AddStock("SKU-A", 5);
        Assert.ThrowsException<InvalidOperationException>(
            () => _sourceWarehouse.TransferTo(_destWarehouse, "SKU-A", 10));
    }

    [TestMethod]
    public void TransferTo_ExceedsStock_DoesNotModifyDestination()
    {
        _sourceWarehouse.AddStock("SKU-A", 5);
        _destWarehouse.AddStock("SKU-A", 10);

        try { _sourceWarehouse.TransferTo(_destWarehouse, "SKU-A", 99); }
        catch (InvalidOperationException) { }

        // source and dest unchanged on failure
        Assert.AreEqual(5, _sourceWarehouse.GetStockLevel("SKU-A"));
        Assert.AreEqual(10, _destWarehouse.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_NullDestination_Throws()
    {
        _sourceWarehouse.AddStock("SKU-A", 10);
        Assert.ThrowsException<ArgumentNullException>(
            () => _sourceWarehouse.TransferTo(null!, "SKU-A", 5));
    }

    [TestMethod]
    public void TransferTo_DestinationAccumulates()
    {
        _destWarehouse.AddStock("SKU-A", 10);
        _sourceWarehouse.AddStock("SKU-A", 30);
        _sourceWarehouse.TransferTo(_destWarehouse, "SKU-A", 8);

        Assert.AreEqual(18, _destWarehouse.GetStockLevel("SKU-A"));
    }
}

